<template>
  <div class="page"><AppNav/><main>
    <header class="hero"><div><small>COURSE SPACES</small><h1>课程空间</h1><p>课程群聊、资料、讨论、作业和成员管理集中在一起。</p></div><div v-if="me.role !== 'teacher' && me.role !== 'admin'" class="join"><el-input v-model="inviteCode" placeholder="输入课程邀请码" maxlength="8"/><el-button type="primary" @click="joinCourse">申请加入</el-button></div></header>
    <section class="course-list" v-if="spaces.length || me.role === 'teacher'"><button v-for="item in spaces" :key="item.id" :class="['course-card',{active:item.id===selectedId}]" @click="select(item.id)"><b>{{ item.name }}</b><span>{{ item.college }} · {{ item.class_name }}</span><small>{{ item.teacher }} · {{ item.member_count }} 位成员<em v-if="item.archived_at"> · 已归档</em></small></button>
      <label v-if="me.role === 'teacher'" class="show-archived"><input type="checkbox" v-model="showArchived" @change="loadSpaces"/> 显示已归档</label></section>
    <el-empty v-if="!spaces.length" :description="me.role === 'teacher' ? '还没有开设课程，或课程都已归档' : '你还没有加入课程空间，请向任课教师获取邀请码'"/>
    <section v-if="space.course" class="workspace" v-loading="loading">
      <div class="workspace-head"><div><small>COURSE SPACE<em v-if="space.course.archived_at"> · 已归档</em></small><h2>{{ space.space.conversation_title || space.course.name }}</h2><p>{{ space.course.college }} · {{ space.course.class_name }} · {{ space.course.teacher }}</p></div>
        <div class="head-actions"><el-button type="primary" @click="openChat">进入课程群聊</el-button>
          <template v-if="isManager"><el-button @click="toggleArchive">{{ space.course.archived_at ? '恢复课程' : '归档课程' }}</el-button><el-button type="danger" plain @click="deleteCourse">删除课程</el-button></template></div></div>
      <div v-if="isManager && space.space.invite_code" class="invite-box"><span>邀请码：<b>{{ space.space.invite_code }}</b><em v-if="space.space.max_uses">（已用 {{ space.space.uses || 0 }}/{{ space.space.max_uses }}）</em></span><small v-if="space.space.expires_at">有效期至 {{ new Date(space.space.expires_at).toLocaleString('zh-CN') }}</small><el-button size="small" @click="copyInvite">复制</el-button><el-button size="small" @click="regenerateInvite">重新生成</el-button></div>
      <el-tabs v-model="tab"><el-tab-pane label="通知与概览" name="overview"><article v-for="n in notices" :key="n.id" class="card"><b>{{ n.is_pinned ? '置顶 · ' : '' }}{{ n.title }}</b><p>{{ n.content }}</p></article><el-empty v-if="!notices.length" description="暂无课程通知"/></el-tab-pane>
        <el-tab-pane label="课程资料" name="resources">
          <div v-if="isManager && !space.course.archived_at" class="upload-row">
            <el-checkbox v-model="reviewRequired" @change="saveReviewRequired">新材料需审核后进入 AI 检索</el-checkbox>
            <el-input v-model="uploadTitle" placeholder="资料标题（可选）" maxlength="100"/>
            <input ref="fileInput" type="file" accept=".pdf,.doc,.docx,.ppt,.pptx,.xls,.xlsx,.csv,.txt,.png,.jpg,.jpeg" @change="pickFile"/>
            <el-button :loading="uploading" @click="uploadResource">上传资料</el-button>
          </div>
          <article v-for="r in resources" :key="r.id" class="card resource"><div><b>{{ r.title }}</b><em v-if="r.review_status === 'pending'" class="pending-tag">待审核</em><p>{{ r.description }}</p><small>{{ r.file_name || r.type }} · {{ r.uploader_name || '课程教师' }}</small></div><button v-if="r.file_path" class="plain-link" @click="openResource(r)">查看资料</button><a v-else-if="r.url" :href="r.url" target="_blank" rel="noopener">打开链接</a></article><el-empty v-if="!resources.length" description="教师还没有上传资料"/></el-tab-pane>
        <el-tab-pane label="课程讨论" name="discussions"><div class="new-post" v-if="!space.course.archived_at"><el-input v-model="newPost.title" placeholder="讨论标题" maxlength="60"/><el-input v-model="newPost.content" type="textarea" :rows="3" placeholder="发表课程讨论" maxlength="5000"/><el-button @click="publishPost">发布讨论</el-button></div><article v-for="post in visibleDiscussions" :key="post.id" class="card"><b>{{ post.title }}</b><small>{{ post.author_name }} · {{ post.comment_count }} 条回复</small><p>{{ post.content }}</p></article><el-empty v-if="!visibleDiscussions.length" description="暂无课程讨论"/><router-link class="more-link" :to="{ path: '/community', query: { course_id: selectedId } }">在论坛中查看全部讨论</router-link></el-tab-pane>
        <el-tab-pane label="课程作业" name="tasks">
          <article v-for="task in tasks" :key="task.id" class="card"><b>{{ task.title }}</b><el-tag size="small">{{ task.task_type }}</el-tag><p>{{ task.description }}</p><small>截止：{{ task.due_at ? new Date(task.due_at).toLocaleString('zh-CN') : '未设置' }}</small>
            <template v-if="isManager"><small>已提交 {{ task.submission_count }} · 待批改 {{ task.pending_count }} · 均分 {{ task.average_score == null ? '—' : Number(task.average_score).toFixed(1) }}</small><el-button size="small" @click="exportGrades(task)" :disabled="!task.submission_count">导出成绩 CSV</el-button></template>
            <template v-else><p v-if="task.submission" class="mine">已提交{{ task.submission.score != null ? `，得分 ${task.submission.score}` : '，等待批改' }}</p><el-input v-if="!space.course.archived_at" v-model="task.draft" type="textarea" :rows="3" placeholder="填写作业提交内容"/><input v-if="!space.course.archived_at" type="file" @change="pickTaskFile(task, $event)"/><el-button v-if="!space.course.archived_at" size="small" @click="submitTask(task)">提交作业</el-button></template>
          </article><el-empty v-if="!tasks.length" description="暂无已发布作业"/></el-tab-pane>
        <el-tab-pane label="成员管理" name="members">
          <article v-if="members.teacher" class="member"><b>教师：{{ members.teacher.name }}</b><span>课程管理员</span></article>
          <div v-if="isManager" class="assistant-box"><b>助教</b><span v-for="a in assistants" :key="a.id" class="assistant">{{ a.name }}<button @click="removeAssistant(a)" title="移除">×</button></span><el-select v-model="assistantId" placeholder="添加教师为助教" size="small" style="width:200px"><el-option v-for="t in assistantCandidates" :key="t.id" :label="t.name" :value="t.id"/></el-select><el-button size="small" @click="addAssistant">添加</el-button></div>
          <article v-for="member in members.members" :key="member.id" class="member"><div><b>{{ member.name }}</b><small>{{ member.college }} · {{ member.class }} · {{ member.student_id }}</small></div><div class="member-actions"><el-button size="small" @click="addFriend(member)" :disabled="member.id===me.id || member.is_friend || member.friend_request_pending">{{ member.is_friend ? '已是好友' : member.friend_request_pending ? '已申请' : '加好友' }}</el-button><el-button v-if="isManager" size="small" type="danger" plain @click="removeMember(member)">移出</el-button></div></article>
          <el-button v-if="members.members?.length && members.members.length < members.total" size="small" @click="loadMoreMembers">加载更多（{{ members.members.length }}/{{ members.total }}）</el-button>
        </el-tab-pane>
      </el-tabs>
    </section>
  </main></div>
</template>
<script setup>
import { computed, onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import AppNav from '../components/AppNav.vue'
import { api, downloadFile, openFile } from '../utils/api'
import { sessionUser } from '../utils/session'

const router = useRouter(), me = sessionUser, spaces = ref([]), selectedId = ref(null), space = ref({}), notices = ref([]), resources = ref([]), discussions = ref([]), tasks = ref([]), members = ref({}), assistants = ref([]), assistantCandidates = ref([]), assistantId = ref(null), inviteCode = ref(''), tab = ref('overview'), loading = ref(false), uploading = ref(false), showArchived = ref(false), reviewRequired = ref(false), uploadTitle = ref(''), uploadFile = ref(null), fileInput = ref(null), newPost = ref({ title: '', content: '' })
const isManager = computed(() => Boolean(space.value.is_teacher))
const visibleDiscussions = computed(() => discussions.value.filter((p) => p.teacher_status !== 'hidden'))
async function loadSpaces () { const query = me.value?.role === 'teacher' && showArchived.value ? '?include_archived=1' : ''; spaces.value = await api(`/courses/spaces${query}`); if (!selectedId.value && spaces.value.length) selectedId.value = spaces.value[0].id; if (selectedId.value && spaces.value.some((item) => item.id === selectedId.value)) await select(selectedId.value) }
async function select (id) { selectedId.value = id; loading.value = true; try { const [detail, noticeRows, resourceRows, discussionRows, taskRows, memberRows] = await Promise.all([api(`/courses/${id}/space`), api(`/courses/${id}/announcements`), api(`/resources?course_id=${id}`), api(`/courses/${id}/discussions`), api(`/courses/${id}/teacher-tasks`), api(`/courses/${id}/members?limit=50`)]); space.value = detail; notices.value = noticeRows; resources.value = resourceRows; discussions.value = discussionRows; tasks.value = taskRows.map(item => ({ ...item, draft: item.submission?.content || '', file: null })); members.value = memberRows; reviewRequired.value = Boolean(detail.course.review_required); if (detail.is_teacher) await loadAssistants() } catch (error) { ElMessage.error(error.message) } finally { loading.value = false } }
async function loadMoreMembers () { const rows = await api(`/courses/${selectedId.value}/members?limit=50&offset=${members.value.members.length}`); members.value = { ...rows, members: [...members.value.members, ...rows.members] } }
async function joinCourse () { if (!inviteCode.value.trim()) return ElMessage.warning('请输入邀请码'); try { const result = await api('/courses/join', { method: 'POST', body: JSON.stringify({ invite_code: inviteCode.value }) }); ElMessage.success(result.message); inviteCode.value = '' } catch (error) { ElMessage.error(error.message) } }
function openChat () { if (space.value.space?.conversation_id) router.push({ path: '/messages', query: { conversation_id: space.value.space.conversation_id } }) }
async function openResource (resource) { try { await openFile(resource.file_path) } catch (error) { ElMessage.error(error.message) } }
async function publishPost () { if (!newPost.value.title.trim() || !newPost.value.content.trim()) return ElMessage.warning('请填写讨论标题和内容'); try { await api('/forum/posts', { method: 'POST', body: JSON.stringify({ ...newPost.value, course_id: selectedId.value }) }); newPost.value = { title: '', content: '' }; discussions.value = await api(`/courses/${selectedId.value}/discussions`); ElMessage.success('讨论已发布') } catch (error) { ElMessage.error(error.message) } }
function pickFile (event) { uploadFile.value = event.target.files?.[0] || null }
function pickTaskFile (task, event) { task.file = event.target.files?.[0] || null }
async function uploadResource () { if (!uploadFile.value) return ElMessage.warning('请选择资料文件'); const body = new FormData(); body.append('course_id', selectedId.value); body.append('title', uploadTitle.value); body.append('file', uploadFile.value); uploading.value = true; try { const result = await api('/resources/upload', { method: 'POST', body }); ElMessage.success(result.message); uploadTitle.value = ''; uploadFile.value = null; if (fileInput.value) fileInput.value.value = ''; resources.value = await api(`/resources?course_id=${selectedId.value}`) } catch (error) { ElMessage.error(error.message) } finally { uploading.value = false } }
async function saveReviewRequired () { try { const result = await api(`/teacher/courses/${selectedId.value}/resource-review`, { method: 'PATCH', body: JSON.stringify({ required: reviewRequired.value }) }); ElMessage.success(result.message) } catch (error) { ElMessage.error(error.message) } }
async function submitTask (task) { if (!task.draft.trim()) return ElMessage.warning('请填写作业内容'); const body = new FormData(); body.append('content', task.draft); if (task.file) body.append('file', task.file); try { const result = await api(`/teacher-tasks/${task.id}/submit`, { method: 'POST', body }); ElMessage.success(result.message); await select(selectedId.value) } catch (error) { ElMessage.error(error.message) } }
async function exportGrades (task) { try { await downloadFile(`/teacher/tasks/${task.id}/submissions.csv`, `task-${task.id}-submissions.csv`) } catch (error) { ElMessage.error(error.message) } }
async function addFriend (member) { if (member.id === me.value?.id) return; try { const result = await api('/friend-requests', { method: 'POST', body: JSON.stringify({ user_id: member.id }) }); ElMessage.success(result.message); member.friend_request_pending = 1 } catch (error) { ElMessage.error(error.message) } }
async function removeMember (member) { try { await ElMessageBox.confirm(`将“${member.name}”移出课程？`, '移出成员', { type: 'warning' }); const result = await api(`/teacher/courses/${selectedId.value}/members/${member.id}`, { method: 'DELETE' }); ElMessage.success(result.message); await select(selectedId.value) } catch (error) { if (error !== 'cancel') ElMessage.error(error.message) } }
async function loadAssistants () { const [list, teachers] = await Promise.all([api(`/teacher/courses/${selectedId.value}/assistants`), api('/teachers')]); assistants.value = list; assistantCandidates.value = teachers.filter((t) => !list.some((item) => item.id === t.id)) }
async function addAssistant () { if (!assistantId.value) return ElMessage.warning('请选择教师'); try { const result = await api(`/teacher/courses/${selectedId.value}/assistants`, { method: 'POST', body: JSON.stringify({ user_id: assistantId.value }) }); ElMessage.success(result.message); assistantId.value = null; await Promise.all([loadAssistants(), select(selectedId.value)]) } catch (error) { ElMessage.error(error.message) } }
async function removeAssistant (assistant) { try { const result = await api(`/teacher/courses/${selectedId.value}/assistants/${assistant.id}`, { method: 'DELETE' }); ElMessage.success(result.message); await Promise.all([loadAssistants(), select(selectedId.value)]) } catch (error) { ElMessage.error(error.message) } }
async function copyInvite () { try { await navigator.clipboard.writeText(space.value.space.invite_code); ElMessage.success('邀请码已复制') } catch { ElMessage.info(space.value.space.invite_code) } }
async function regenerateInvite () { const days = window.prompt('有效期（天，默认 14）', '14'); if (days === null) return; const maxUses = window.prompt('最多可批准人数（0 为不限）', '0'); if (maxUses === null) return; try { const result = await api(`/teacher/courses/${selectedId.value}/regenerate-invite`, { method: 'POST', body: JSON.stringify({ expires_days: Number(days), max_uses: Number(maxUses) }) }); space.value.space = { ...space.value.space, invite_code: result.invite_code, expires_at: result.expires_at, max_uses: result.max_uses, uses: 0 }; ElMessage.success(result.message) } catch (error) { ElMessage.error(error.message) } }
async function toggleArchive () { const archived = !space.value.course.archived_at; try { const result = await api(`/teacher/courses/${selectedId.value}/archive`, { method: 'PATCH', body: JSON.stringify({ archived }) }); ElMessage.success(result.message); space.value.course.archived_at = archived ? new Date().toISOString() : ''; await loadSpaces() } catch (error) { ElMessage.error(error.message) } }
async function deleteCourse () { try { await ElMessageBox.confirm('永久删除课程及其资料、作业和群聊？该操作不可撤销。', '删除课程', { type: 'warning' }); const result = await api(`/teacher/courses/${selectedId.value}`, { method: 'DELETE' }); ElMessage.success(result.message); selectedId.value = null; await loadSpaces() } catch (error) { if (error !== 'cancel') ElMessage.error(error.message) } }
onMounted(loadSpaces)
</script>
<style scoped>
.page{min-height:100vh;background:#fffaf6;color:#633e2e}main{width:min(1180px,94vw);margin:auto;padding:34px 0 70px}.hero,.workspace-head{display:flex;justify-content:space-between;gap:22px;align-items:end}.hero h1{margin:6px 0;color:#633c2c;font-size:32px}.hero p,.workspace-head p{color:#97786a}.hero small,.workspace-head small{font-size:11px;letter-spacing:1.5px;color:#b2694e;font-weight:800}.join{display:flex;gap:8px;min-width:330px}.course-list{display:flex;gap:12px;overflow:auto;margin:28px 0;align-items:center}.show-archived{display:flex;gap:5px;align-items:center;white-space:nowrap;font-size:12px;color:#8f7263}.course-card{border:1px solid #efdcd0;background:#fffdfa;border-radius:17px;padding:14px 16px;min-width:210px;text-align:left;color:#795b4d;cursor:pointer}.course-card.active{border-color:#cf7953;background:#fff0e5}.course-card b,.course-card span,.course-card small{display:block}.course-card span{margin-top:8px;color:#a87865;font-size:12px}.course-card small{margin-top:5px;color:#af9385;font-size:11px}.course-card em{font-style:normal;color:#aa6b45}.workspace{margin-top:24px;background:#fffdfa;border:1px solid #efdfd5;border-radius:23px;padding:22px;box-shadow:0 10px 30px #9f4c2b0d}.workspace-head{align-items:center;border-bottom:1px solid #f3e5dd;padding-bottom:16px}.workspace-head h2{margin:7px 0;color:#633c2c}.head-actions{display:flex;gap:8px;flex-wrap:wrap}.invite-box{display:flex;gap:10px;align-items:center;flex-wrap:wrap;background:#fff5e9;border-radius:13px;padding:9px 12px;margin-top:14px;font-size:13px;color:#8a5c43}.invite-box small{color:#a38472}.card{background:#fffaf6;border:1px solid #f0e1d8;border-radius:15px;padding:15px;margin:12px 0}.card b{color:#704432}.card p{white-space:pre-wrap;line-height:1.65;color:#81675c}.card small,.member small{display:block;color:#a38678;margin-top:7px}.resource{display:flex;justify-content:space-between;gap:15px}.plain-link{border:0;background:transparent;color:#ae5d3e;cursor:pointer;font-size:13px;padding:0}.new-post{display:grid;gap:9px;margin:12px 0}.member{display:flex;justify-content:space-between;align-items:center;gap:15px}.member span{color:#ae816d;font-size:12px}.member-actions{display:flex;gap:6px}.pending-tag{font-style:normal;background:#fae7bd;color:#8d6420;border-radius:8px;padding:2px 6px;font-size:11px;margin-left:7px}.mine{color:#56805b!important}.more-link{display:inline-block;margin-top:8px;color:#ae5d3e;font-size:13px}.upload-row{display:flex;gap:9px;align-items:center;flex-wrap:wrap;background:#fff5e9;border-radius:13px;padding:10px;margin-top:10px}.assistant-box{display:flex;gap:8px;align-items:center;flex-wrap:wrap;padding:9px 0;border-bottom:1px solid #f2e5dc}.assistant{background:#f5ede4;border-radius:9px;padding:3px 6px;font-size:12px}.assistant button{border:0;background:transparent;color:#a4503a;cursor:pointer}@media(max-width:700px){.hero,.workspace-head{align-items:start;flex-direction:column}.join{width:100%;min-width:0}.resource,.member{align-items:start;flex-direction:column}}
</style>
